import pandas as pd
rent = pd.Series([150.0, 200.0, 260.0, 310.0, 99999.0], name="monthly_rent")

def minmax(s):
    return (s - s.min()) / (s.max() - s.min())

def standard(s):
    return (s - s.mean()) / s.std()

def robust(s):
    q1, q3 = s.quantile(.25), s.quantile(.75)
    return (s - s.median()) / (q3 - q1)

print("min-max :", minmax(rent).round(6).tolist())
print("standard:", standard(rent).round(4).tolist())
print("robust  :", robust(rent).round(4).tolist())
LIMITS = (50, 2000)
repaired = rent.mask(~rent.between(*LIMITS))
print("min-max after the repair:", minmax(repaired).round(4).tolist())
